class PromptPipeline:
    def __init__(self):
        self._steps = []

    def add_template(self, name, template):
        self._steps.append({'name': name, 'template': template})
        return self

    def fill(self, template, variables):
        result = template
        for key, value in variables.items():
            result = result.replace('{' + key + '}', str(value))
        return result

    def run(self, variables):
        return [{'name': step['name'], 'output': self.fill(step['template'], variables)} for step in self._steps]

    def missing_vars(self, variables):
        needed = set()
        for step in self._steps:
            t = step['template']
            i = 0
            while True:
                start = t.find('{', i)
                if start == -1:
                    break
                end = t.find('}', start)
                if end == -1:
                    break
                needed.add(t[start + 1:end])
                i = end + 1
        return sorted(needed - set(variables.keys()))
